Deno.test("integrations model: response schemas tolerate unexpected data", () => {
  // connections: empty entity (every field absent) still validates.
  assertEquals(
    resourceSchema("connections").safeParse({
      items: [{}],
      truncated: false,
      fetchedAt: "2024-01-01T00:00:00Z",
    }).success,
    true,
  );
  // connections: unknown keys are preserved, not stripped or rejected.
  {
    const parsed = resourceSchema("connections").safeParse({
      items: [{ unexpected_field: 1 }],
      truncated: false,
      fetchedAt: "2024-01-01T00:00:00Z",
    });
    assertEquals(parsed.success, true);
    // A plain z.object would also succeed, but would strip the key.
    assertEquals(
      JSON.stringify(parsed.data).includes("unexpected_field"),
      true,
    );
  }
  // connection: empty entity (every field absent) still validates.
  assertEquals(resourceSchema("connection").safeParse({}).success, true);
  // connection: unknown keys are preserved, not stripped or rejected.
  {
    const parsed = resourceSchema("connection").safeParse({
      unexpected_field: 1,
    });
    assertEquals(parsed.success, true);
    // A plain z.object would also succeed, but would strip the key.
    assertEquals(
      JSON.stringify(parsed.data).includes("unexpected_field"),
      true,
    );
  }
  // token: empty entity (every field absent) still validates.
  assertEquals(resourceSchema("token").safeParse({}).success, true);
  // token: unknown keys are preserved, not stripped or rejected.
  {
    const parsed = resourceSchema("token").safeParse({ unexpected_field: 1 });
    assertEquals(parsed.success, true);
    // A plain z.object would also succeed, but would strip the key.
    assertEquals(
      JSON.stringify(parsed.data).includes("unexpected_field"),
      true,
    );
  }
  // integrations: empty entity (every field absent) still validates.
  assertEquals(
    resourceSchema("integrations").safeParse({
      items: [{}],
      truncated: false,
      fetchedAt: "2024-01-01T00:00:00Z",
    }).success,
    true,
  );
  // integrations: unknown keys are preserved, not stripped or rejected.
  {
    const parsed = resourceSchema("integrations").safeParse({
      items: [{ unexpected_field: 1 }],
      truncated: false,
      fetchedAt: "2024-01-01T00:00:00Z",
    });
    assertEquals(parsed.success, true);
    // A plain z.object would also succeed, but would strip the key.
    assertEquals(
      JSON.stringify(parsed.data).includes("unexpected_field"),
      true,
    );
  }
  // integration: empty entity (every field absent) still validates.
  assertEquals(resourceSchema("integration").safeParse({}).success, true);
  // integration: unknown keys are preserved, not stripped or rejected.
  {
    const parsed = resourceSchema("integration").safeParse({
      unexpected_field: 1,
    });
    assertEquals(parsed.success, true);
    // A plain z.object would also succeed, but would strip the key.
    assertEquals(
      JSON.stringify(parsed.data).includes("unexpected_field"),
      true,
    );
  }
});

/**
 * Paths swamp vaults in a resource schema: fields carrying
 * .meta({ sensitive: true }) on the field or on an optional, nullable or
 * default wrapper around it, found by walking plain object shapes only (swamp
 * does not enter arrays or unions, or see through readonly or catch).
 */
function swampSensitivePaths(schema: unknown, prefix = ""): string[] {
  // deno-lint-ignore no-explicit-any
  const inner = (s: any): any =>
    ["optional", "nullable", "default"].includes(s?._zod?.def?.type)
      ? s._zod.def.innerType
      : undefined;
  // deno-lint-ignore no-explicit-any
  const unwrap = (s: any): any => {
    while (inner(s)) s = inner(s);
    return s;
  };
  // deno-lint-ignore no-explicit-any
  const isMarked = (s: any): boolean => {
    for (let cur = s; cur; cur = inner(cur)) {
      if (cur.meta?.()?.sensitive === true) return true;
    }
    return false;
  };
  const obj = unwrap(schema);
  if (obj?._zod?.def?.type !== "object") return [];
  const out: string[] = [];
  for (const [key, field] of Object.entries(obj._zod.def.shape)) {
    const path = prefix ? prefix + "." + key : key;
    if (isMarked(field)) out.push(path);
    out.push(...swampSensitivePaths(field, path));
  }
  return out.sort();
}

Deno.test("integrations model: token resource marks credential fields sensitive", () => {
  assertEquals(
    swampSensitivePaths(resourceSchema("token")),
    ["access_token"],
  );
});

