Deno.test({
  name: "integrations model: a 429 is retried after Retry-After",
  sanitizeResources: false,
  fn: async () => {
    const fixture = { "access_token": "test-value" };
    await withMockApi({
      "GET /api/connections/test-id-123/access-token": [
        { status: 429, headers: { "Retry-After": "0" }, json: {} },
        { json: fixture },
      ],
    }, async ({ run, requests }) => {
      const result = await run("get_token", { "connection_id": "test-id-123" });
      assertEquals(result.dataHandles.length, 1);
      assertEquals(requests.length, 2);
    });
  },
});
